seen = {}
if os.path.exists(OUT):
    for x in json.load(gzip.open(OUT, 'rt', encoding='utf-8')):
        if x.get('g') not in GROUPS: seen[x['vid']] = x
nz = lambda t: re.sub(r'[^a-z0-9]+', ' ', t.lower()).strip()
for g in GROUPS:
    for n, q in enumerate(Q[g]):
        if time.time() - T0 > BUDGET: break
        try: rs = E.search(q, pages=1 if g in ('promo', 'xmasmv') else 2, long=False)
        except Exception as e: print('fail', q, e, flush=True); continue
        lo, hi = LEN[g]
        for r in rs:
            t = r.get('t') or ''; d = int(r.get('dur') or 0)
            if BAD.search(t) or not (lo <= d <= hi): continue
            if g == 'holspec' and q in HM:
                if not re.search('(?i)' + HM[q], t): continue
            elif not KEEP[g].search(t): continue
            ad = date_of(t)
            if g == 'xmasmv':
                so = XM[q]; w = [x for x in nz(so[1]).split() if len(x) > 2]
                if sum(1 for x in w if x in nz(t)) < max(1, (len(w) + 1) // 2) or re.search(r'(?i)karaoke|lyric|cover|instrumental|piano|guitar|8d|slowed|reverb|nightcore|tutorial|live at|live in|reaction|1 hour|10 hours', t): continue
                ad = str(so[2])
            elif g == 'holspec':
                ad = ad or str(HY.get(q, ''))
            if not ad and g not in ('infomercial', 'signoff'): continue
            k = r['vid']
            if k not in seen: seen[k] = {'vid': k, 't': t[:200], 'ch': (r.get('ch') or '')[:80], 'dur': d, 'ad': ad, 'g': g, 'q': q}
            if g == 'xmasmv' and k in seen: break
        if n % 25 == 0: print(g, n, len(Q[g]), q, 'kept', len(seen), round((time.time() - T0) / 60, 1), flush=True)
L = sorted(seen.values(), key=lambda x: (x['g'], x['ad'], x['vid']))
